    profileTitle: 'İctimai profilinizi və ya kanalınızı fərdiləşdirin və yeniləyin',
    profileDesc: 'İstədiyiniz vaxt izləyicilərinizin məlumatlarını ixrac edə bilərkən istifadəçilərin nələri görə biləcəyinə və ya görə bilməyəcəyinə nəzarət edin. Bu, kanalınıza tam sahiblik imkanı verir və nə baş verməsindən asılı olmayaraq biznesinizi özünüzlə istənilən yerə aparmağa imkan verir.',
