    topUpShotAlt: 'DeHub tokenlərinin birbaşa tətbiq daxilində satın alınması.',
    topUpDesc: 'Fortnite və ya TikTok pullarında əldə etdiyiniz Vbucks-a bənzər tətbiq valyutamız var, bizimki DeHub ayələridir. Bunları tətbiqdə qızıl sikkələr kimi görəcəksiniz. Onlar ipucları, abunəliklər və s. kimi mükafat xidmətləri üçün istifadə olunur. Baxmaq pulsuzdur və buna görə də hər bir hesab gündəlik müavinətin içərisində yerləşdirilir — əgər siz sosiallar, e-poçt və ya SMS ilə qeydiyyatdan keçirsinizsə, biz sizin üçün bütün qaz haqlarına sponsorluq edirik. Pul kisəsi istifadəçiləri standart ETH və ya BNB qazı ödəyir. Aşağıdakı 2 kliklə yuxarı ayələr.',
