    secureGateway: 'Təhlükəsiz Şlüz',
    secureGatewayDesc: 'Bütün ödəniş təfərrüatları Stripe tərəfindən təhlükəsiz şəkildə şifrələnir və emal edilir. Həssas məlumatlarınıza və ya kart təfərrüatlarınıza daxil ola və ya onları saxlaya bilmirik. Bu, son dərəcə rahatlığınızı təmin edir.',
    importantNotice: 'Vacib Bildiriş',
    tokenDisclaimer: 'DeHub tokenləri ekosistemimiz daxilində oyun valyutalarına bənzər kommunal tokenlər rolunu oynayır və investisiya vasitələri deyil. Blockchain infrastrukturumuz təhsil məqsədləri üçün misli görünməmiş şəffaflıq və təsdiq edilə bilən şəbəkə məlumatları təmin etsə də, bütün bazarlar özünəməxsus risklər daşıyır. Bazar dəyişkənliyi, texniki problemlər, təhlükəsizlik pozuntuları və ya gözlənilməz hallar səbəbindən bütün sərmayənizi itirə bilərsiniz. Yalnız tamamilə itirə biləcəyiniz vəsaitlərlə iştirak edin. DeHub və onun filialları yaranan hər hansı maliyyə itkisinə görə heç bir məsuliyyət daşımır.',
    exploreTitle: 'Tətbiq və Beyond-u araşdırın',
    exploreDesc: 'Axtarış çubuqları birdən çox tətbiqə sarılaraq qənaət etməyiniz üçün YouTube və digər əsas axın tətbiqi API-ləri toplayır, araşdırın səhifəsində isə aşağıdakılar üçün canlı icma söhbətimiz və xüsusi lider lövhələrimiz var:',
    exploreFormula: 'Bu birlikdə reklam gəliri payını (RS) müəyyən edəcək. Bunun dəqiq alqoritmi betanın altındadır və əldə edilən gəlirdən asılı olaraq dəyişə bilər (RG)',
