    badgeTitle: 'Nişanınızı Flex edin',
    badgeSubtitle: 'Şərəf Nişanı Modeli',
    badgeDesc: 'Nə qədər çox DeHub işarəsi saxlasanız, o qədər çox savab qazanarsınız, bu qədər sadə. Buraya ictimai profilinizdəki təkmilləşdirilmiş kosmetik vasitələri, eləcə də daha da təkmilləşdirilmiş, premium xüsusiyyətləri üzə çıxaran Şərəf Nişanı daxildir, lakin bununla məhdudlaşmır.',
    badgePriceTitle: 'Nərdivanın qiyməti dollarla hesablanır',
    badgePriceDesc: 'Meqalodon vasitəsilə Krab (Meqalodon) adlı on üç tirajın hər biri sabit sayda tokenə deyil, sabit məbləğdə dollara başa gəlir. DeHub tokenlərinin sayı bir səviyyə tələb edir ki, dollar canlı qiymətə başa gəlir, buna görə də nişan bazarın gördüyü hər iş üçün eyni öhdəlik deməkdir. İki qoruma tətbiq edilir: qiymət düşdükdə tələb heç vaxt dərc edilmiş rəqəmlərdən yuxarı qalxmır və siz onu saxlayacağınız bir səviyyəyə çatdıqdan sonra qazandığınız nişan indiyə qədər qazanılmış ən ucuz tələbə kilidlənir, buna görə də dalğıc onu sizdən uzaqlaşdıra bilməz.',
    badgeUnlockTitle: 'Nişan necə bloklanır?',
    badgeUnlock1: 'İpucları, ödəmələr, abunəlik və lütflər üzrə daha aşağı haqq, 0,69% pillə geriləyərək.',
    badgeUnlock2: 'Daha böyük pulsuz gündəlik poçt icazəsi və keçmiş hər hansı bir şey üçün endirim.',
    badgeUnlock3: 'DeHub tokenləri satın alarkən eyni endirim, Crab-da 5% -dən Megalodon-da 30% -ə qədər.',
    badgeUnlock5: 'Etdiklərinizdən daha çox ağırlıq: nişan sahibinin görünüşü və ya reaksiyası daha çox, idarəetmə səsverməsi ilə eyni nərdivanda — bir nişan olmadan, ikisi Crab-da və Meqalodonda on dördə qədər yuxarıdakı hər bir pillə üçün daha çox hesablanır. Bu, bir reaksiyanızda çoxluq təşkil edir, ikinci reaksiyanızda isə heç vaxt.',
    badgeDelegationTitle: 'Nişanınızı uzadın',
    badgeDelegationDesc: 'Nişan lentə alına bilər. Qalxdığınız hər bir pillə sizə bir nümayəndə aralıqları verir — biri Crab-da, on üçü Meqalodonda və hər bir aralıq oranı tərk etdiyiniz müddətcə başqa bir pilləyə əl atır. Bu, DeHub-a təsirin tək bir cüzdan üzərində oturmaqdan daha çox bir qrupla səyahət etmək üçün nəzərdə tutulduğuna görə mövcuddur: ekipajlar, komandalar və ikinci hesablar heç kim tokenləri hərəkət etdirmədən və ya açarları təhvil vermədən, arxa sıralarda tutduqları pillələri əldə edirlər.',
