    badgeDelegationB3: 'Himayəçi hər kəsə açıqdır:',
    badgeDelegationB3Desc: 'Tətbiqin istənilən yerində nümayəndəli nişandan imtina edin və ona dəstək verən adları verin. Səviyyənin haradan gəldiyi barədə heç nə gizlədilmir.',
    badgeDelegationB4: 'İstənilən vaxt geri qaytarıla bilər:',
    badgeDelegationB4Desc: 'Arada aralıq götürün və pillə sizə qayıdır. Borc verdiyiniz hər hansı bir şeyə görə öz stake, haqq pilləsi və kilidli nişanınız toxunulmazdır.',
    badgeDelegationB5: 'Status, hüquqlara malik deyil:',
    badgeDelegationB5Desc: 'Mərc nişanı platformanın göstərdiyi şeydir və o, pillə ilə gedən ağırlığı daşıyır — baxış və ya ondan gələn reaksiya lentin lentə alındığı pillə ilə hesablanır. Daşıya bilmədiyi şey pulla qiymətləndirilən bir şeydir: haqq səviyyəniz, möcüzə alış endirimi, gündəlik poçt icazəsi və öz nümayəndə heyətinin slotları hələ də özünüzü saxladığınız paydan oxunur.',
