    tipDesc2: 'Yaradıcılar üçün alınan ipucları və izləyicilər tərəfindən verilən ipucları reklam gəlirindəki payları müəyyən edən izləyici sayları və abunəçilərlə birlikdə ayrı-ayrı lider panellərinə daxil olur. DeHub tokenlərinin maraqlı tərəfləri ümumi protokol mənfəətinin mütənasib paylarını alırlar.',
