    mineDesc2: 'Yalnız əsas komanda və ya ən yüksək dərəcəli nişan sahibləri NFT ilə əlaqəli videonu yandıraraq dərhal silmək səlahiyyətinə malik olacaq. Daha sonra, əldə edilən bütün reklam gəliri və videoya vurulan lütfləri qazanmaq üçün istənilən oyun pis aktyorları daha da zərərsizləşdirmək və məşğul icmanı həvəsləndirmək üçün bütün səsvermə cüzdanları ilə paylaşılacaq.',
