    superPowersTitle: 'Super Güclər',
    superPowersDesc: 'Super Güclər xərcləyə biləcəyiniz paylama nişanını əlçatan edir. Nişanınızın verdiyi hər gecə artır və xərcləmək üçün ev yeminin yuxarısındakı yuvaya yazı yerləşdirin. Komanda hər kəs üçün açıqdır və səkkiz hesaba qədər cüzdan gücünü birləşdirir və hər üzvə ümumi kilidlərini nişan verir. Slot fırlanır: bir neçə təkan olduqda izləyicilər nişan pillələri ilə bir ağırlıqda olurlar, buna görə də daha yüksək səviyyə daha tez-tez göstərilir və hamı hələ də onlara verilən pəncərəni alır.',
    superPowersDescV2: 'Super Güclər xərcləyə biləcəyiniz paylama nişanını əlçatan edir. Nişanınızın verdiyi hər gecə artır və xərcləmək üçün ev yeminin yuxarısındakı yuvaya yazı yerləşdirin. Komanda hər kəs üçün açıqdır və səkkiz hesaba qədər cüzdan gücünü birləşdirir və hər üzvə ümumi kilidlərini nişan verir. Slot fırlanır: bir neçə təkan olduqda izləyicilər nişan pillələri ilə bir ağırlıqda olurlar, buna görə də daha yüksək səviyyə daha tez-tez göstərilir və hamı hələ də onlara verilən pəncərəni alır.',
