    timelineBomber: '5) Zaman Şkalası Bombardmançısı',
    timelineBomberDesc2: 'İzləyiciləriniz postunuzu başqalarından üstün görür — Kral Kobra sizdən eşitməyi seçən insanlar üçün Meqalodonu döyür. King Cobra-da kilidləri açın. İndi yaşayın.',
