    harpoon: '9) **Harpoon**',
    harpoonDesc: 'Seçdiyiniz nişan pillələrindəki hər bir sahibinə bir yazı haqqında məlumat verin. Tiger Shark-da kilidləri açın. İndi yaşayın.',
    superPowersMore2: 'On iki qüvvənin hamısı dərc edilib və tətbiqdə göstərilib. Anker şərhinizi başqasının düzümünün üstündə saxlayır. Siqnal Parıltısı sizi izləyən hər hesaba bir bildiriş göndərir. Flak gödəkçəsi işə düşərkən enişli-yoxuşlu dəfnlərə qarşı immunitet yaradır. Komanda səkkiz hesab qədər cüzdan gücünü birləşdirməyə imkan verir, buna görə də hər bir üzv nişanı hovuzlu balansını blokdan çıxarır. Ön Sıra ev sahibliyi etdiyiniz Mərhələni dəmir yolunun yuxarısında yerləşdirir. Dərin Cari təkanlarınızdan birini başqasının postuna verir.',
