    feeTierDesc: 'İnqilabi haqq strukturumuz DeHub marker sahiblərini platforma haqlarını əhəmiyyətli dərəcədə azaltmaqla mükafatlandırır. Standart 10% -lik haqdan başlayaraq, artan mötəbər holdinqlər vasitəsilə qazanılan hər bir nişan pilləsi haqları 0,69% azaldır, nəticədə Meqalodon nişanı sahibləri üçün cəmi 1% -ə çatır - ən xüsusi icma üzvlərimiz üçün 99% -lik haqq azalması.',
