    feeDisclaimer: 'Mühüm Haqq İmtina',
    feeDisclaimerDesc: 'Haqlar yalnız ipucları, abunəliklər, ödəmələr və watch2earn lütfləri kimi müəyyən xidmətlərə tətbiq olunur. İstifadəçilər tətbiqdə işarələri digər istifadəçilərə pulsuz göndərə və bunu cüzdan ünvanı və ya ayrıca açar idarəetməsi tələb olunmadan etmək üçün abstraksiya alətlərimizdən istifadə edə bilərlər.',
