    altMusic: 'Musiqilər, videolar, podkastlar və radiostansiyaları əhatə edən Musiqi mərkəzi.',
    altWallet: 'Daxili cüzdan, mötərizə balanslarını və Qəbul Et, Göndər, Al, Paylaş, Körpü və Nağd Pul Çıxarma əməliyyatlarını göstərir.',
    altCommandCentre: 'Gəlir və əməliyyatlar üçün maliyyə göstəricilər paneli olan Komanda Mərkəzi.',
