    povrTitle: 'POVR: Baxış Sıralamanın Sübutu',
    povrDesc1: 'Reklam texnologiyalı həllimiz miras və ya Blockchain bazarlarında görünən hər şeydən fərqlidir və öz tətbiqimiz daxilində unikal bir məqsədə xidmət edir.',
    povrDesc2: '"Baxış Sübutu" bir ölçülü və identifikasiyadan kənardır, istifadəçilər və ya sahiblər üçün az fayda əlavə edir.',
    povrDesc3: 'Blok yeri və ya qaz sərf etmədən izləyicilərin həqiqi olduğunu sübut edə bilsəniz, nə baş verər? Yalnız xərclərə qənaət etmək üçün deyil, həm də kampaniyalarınız üçün ROI-ni maksimal dərəcədə artırmaq üçün hər bir cüzdanın maliyyə məlumatlarından yararlana bilsəniz, nə baş verər? Yalnız daha çox pul qazanmayın, daha çox qazanın!',
    povrDesc4: 'Patentləri gözləyən proqram təminatımız bunu bu əvvəlki xüsusiyyət diqqət mərkəzində vurğulanan təsdiqləmə nişanlarımızla birlikdə görünməmiş 13 dərəcəli sıralama sistemi vasitəsilə edir.',
