    howItWorks: 'İş prinsipi',
    howItWorksDesc1: 'Ümumi tutmalarınız nə qədər yüksək olarsa, kiliddən nə qədər yüksək reytinqli nişan çıxarsanız, reklamlardan nə qədər çox qazansanız, sizə reklam vermək üçün bir o qədər çox şirkət ödəyəcək.',
    howItWorksDesc2: 'Bu yolla tək şənlik deyil, bütün ekosistemə fayda verir. Platformada reklam verən məzmun yaradıcıları, istehlakçılar, sahiblər və şirkətlər daha çox mükafat qazanırlar.',
    howItWorksDesc3: 'Maliyyə məlumatları ən gəlirlidir və bizim unikal bir sistem reklamçıları hədəf auditoriya üçün istifadə edə bilər. Blockchain ictimai olduğu halda bank çıxarışları məxfi olduğu üçün bu, hətta şəbəkə xaricində edə biləcəyiniz bir şey deyil.',
    howItWorksDesc4: 'Balinaları və böyük xərcləyiciləri hədəf ala bilmək, eyni zamanda dənizdəki kiçik balıqlar üçün xüsusi təkliflər və ya endirimlər hazırlamaq bütün dünyada reklamın iş prinsipini yenidən formalaşdıracaq. Niyə bunu heç kim istəməsin?',
    preventFraud: 'Bu, saxtakarlığın qarşısını necə alır?',
    preventFraudDesc1: 'Fəaliyyət zənciri izləyə bilən, pis aktyorları asanlıqla birləşdirən və nəticədə bütün istifadəçi bazasını əhatə edən botting daha az gəlirli olur. Reklamçılar qalan fırıldaqçılıqların qaldığı aşağı təbəqədə minimal çıxarıla bilən dəyər qoyaraq daha yüksək sıraları hədəfləyirlər. Bundan əlavə, mərkəzləşmiş moderatorluğumuz daha səmərəli qanunsuz fəaliyyətin aşkarlanması və qarşısının alınmasına imkan verir.',
    preventFraudDesc2: 'Reklam gəliri paylaşımımız haqqında ətraflı məlumat üçün bu düzümə və aşağıdakı ağ kağızımıza istinad edin. Həmçinin tətbiq xüsusiyyətləri və yeniləmələrlə bağlı bütün ən son xəbərlər üçün bizi izlədiyinizə əmin olun.',
