    corePrinciple: 'Əsas prinsip: biz hesabın işləməsi üçün lazım olan minimal məbləği toplayırıq, onu heç vaxt satmırıq və cihazınızda və ya ictimai şəbəkədə qalan hər şeyi toplayırıq.',
