    lastUpdatedDate: '29 sentyabr 2026-cı il',
    doCollectItem1: 'Bu marşrutlardan birini seçdiyiniz halda imzaladığınız identifikator — e-poçt ünvanı və ya telefon nömrəsi, sosial olaraq imzaladığınız şəxsiyyət Google, Apple və ya Telegram, yaxud da passkey-in ictimai etimadnaməsini geri qaytarır. Pul kisəsi işarəsi bizə ictimai ünvanınızdan başqa heç nə vermir.',
