  tokenOverview: {
    title: 'İcmal',
    subtitle: 'DeHub-u gücləndirən valyuta',
    intro: 'DeHub tokenləri DeHub şəbəkəsinin yerli kommunal valyutasıdır; DHB onların gənə simvoludur. Onlar hər bir tətbiq üzrə hesabın vahid vahid vahididir — ipucu verdiyiniz şey, məzmunun kilidini açmaq, izləmək və yaratmaq üçün qazanc əldə etmək və AI nəslinə xərcləmək. Zəncirvari şəkildə yaşadıqlarına görə, ekosistemdəki hər bir dəyər hərəkəti sözümüzü tutmalı olduğunuz xüsusi karnizdə oturmaqdansa, ictimai şəkildə təsdiqlənə bilər.',
    howItWorksTitle: 'Valyutanın tətbiqdə iş prinsipi',
    howItWorksDesc1: 'Hər bir DeHub hesabında bir cüzdan var. Zolaqlı şlüzümüz vasitəsilə onu kartla maliyyələşdirə, başqa istifadəçidən ala, platformadan qazana və ya özünə məxsus hər hansı cüzdanı depozit qoya bilərsiniz — başlamaq üçün ayrıca tətbiq, genişləndirmə və ya toxum ifadəsi tələb olunmur. Balanslar, ipucları, bloklar və mükafatlar hamısı DeHub tokenlərində yerləşir, buna görə də dəyər birbaşa istifadəçilər arasında hərəkət edir, əvəzində ödəniş prosessoru vasitəsilə yönləndirilir və hesabı dondura bilər.',
    howItWorksDesc2: 'Holdinq və stake də tətbiqin sizin üçün necə davrandığını dəyişir. Nə qədər çox DeHub işarəsi saxlasanız, platforma haqlarınız nə qədər az olsa və kilidinizi açmaq imkanınız nə qədər çox olsa — nişan, təsdiqləmə, trend artırmaları, klub pillələri və şəbəkə daxilində inkişaf etmiş hüquqlar. Təcrübədə valyuta bolt deyil: bu, icazə qatı, mükafat dəmir yolu və eyni zamanda çıxışdır.',
    useCasesTitle: 'Nə üçün istifadə olunur',
    useTippingTitle: 'Yaradıcılara ipucu vermək',
    useTippingDesc: 'Birbaşa, qısa, yayım və ya səhnədə — dərhal, qlobal səviyyədə və köçürməni üzən ortam olmadan bir yaradıcıya dəyər göndərin.',
    useContentTitle: 'Məzmunun alınması',
    useContentDesc: 'Ödəniş baxışı yükləmələri, işarəli kilidli ismarıclar, mükafat mesajları və yaradıcı abunələri kiliddən çıxarın. Yaradıcıya 30 gün sonra deyil, kiliddən çıxarma zamanı ödəniş edilir.',
    useRewardsTitle: 'Mükafat valyutası',
    useRewardsDesc: 'x-2-qulluq ödəmələr, mükafatlara baxmaq, dərc edilmiş məzmun üzrə güzəştlər, zəfərlər, oyunlar və icma kampaniyaları DeHub tokenlərində denominasiya edilir və ödənilir.',
    useCommerceTitle: 'Mağazalar və bazar',
    useCommerceDesc: 'Bir balansdan istifadə edərək məhsulları, rəqəmsal kolleksiya məhsullarını, xidmətləri və Fitital NFT-ləri yaradıcı mağazalardan və bazardan alın.',
    useFeesTitle: 'Haqlar, staking və idarəetmə',
    useFeesDesc: 'Şəbəkə haqları ödəyin, protokolun gəlir payına görə klub pillələrinə sahib olun və protokol qərarlarında idarəetmə səsləri toplamaq üçün DeHub tokenlərini yandırın.',
    profitShareTitle: 'Mənfəət payı',
    profitShareDesc1: 'DeHub şəbəkədən istifadə edən insanların ona sahib olması üçün dizayn edilib. Protokol gəliri — platforma haqları, mağaza və bazar haqları, reklam, AI istifadəsi və oyun gəliri — yeni hazırlanmış təchizat deyil, real gəlirli bölüşdürmələr və geri ödəmə şəklində pay sahiblərinə geri qayıdır. DeHub tokenlərinə sahib olmaq buna görə də yalnız xərc balansı deyil, DeHub şəbəkəsinin özünün payına sahiblikdir.',
    profitShareDesc2: 'Paylamalar protokolun faktiki olaraq qazandığından, dəyişən aralıqlarla maliyyələşdirilir və həm məbləğə, həm də stekasiya müddətinə görə pillələr üzrə bölüşdürülür. Daha uzun öhdəlik hər paydan daha böyük pay əldə edir. Səviyyə mexanikası və dəqiq mükafat hesablanması üçün Pay-a baxın.',
    pegTitle: 'Qiymət və İNDEKS ELANI',
    pegDesc1: 'DeHub tokeni faydalı bir işarədir. Tətbiqdaxili məqsədlər üçün hazırda hər marker üçün $ 0.001 hesablanır ki, bu da fiat şlüzü vasitəsilə satın alarkən gördüyünüz qiymət və tətbiqdaxili qiymətləndirmə üçün istifadə olunan qiymətdir. Bu mıx şəbəkə ölçülərkən tətbiqdaxili iqtisadiyyatı sabit və proqnozlaşdırıla bilən saxlamaq üçün mövcuddur — bu, daxili uçot dərəcəsidir, döşəmə, zəmanət və ya gələcək dəyər vəd etmir.',
    pegDesc2: 'Mərkəzləşmiş birjalarda, likvidlik hovuzları ilə bir neçə zəncirdə eyni 0.001 baza qiymətindən toxumuş mö \'cüzə ticarətləri. Açıq bazarda qiymət DeHub tərəfindən deyil, ticarət yolu ilə təyin edilir — bu o deməkdir ki, DeHub tokenləri istənilən vaxt tətbiqdaxili mıxın üstündə və ya altında ticarət edə bilər. DeHub, hər bir əməliyyatın hər kəsə açıq şəkildə təsdiqlənə bilməsi üçün DEX-lərdə rəsmi likvidliyini toxuyur.',
    disclaimer: 'İmtina',
    disclaimerNoApy: 'Vacibdir: DeHub tokenləri DeHub şəbəkəsində sahiblik hüququ verir və istehsalçılara protokol mənfəəti payı verir, APY təyin edilmir, zəmanətli geri dönüş dərəcəsi və hər hansı bir mənfəət gözləntisi yoxdur. Bütün distributivlər tamamilə şəbəkə performansından və protokolun müəyyən bir dövrdə əldə etdiyi gəlirdən asılıdır. Mükafatlar əvvəlki dövrlə müqayisədə daha az və sıfır ola bilər. Bu səhifədəki heç bir şey vəd, proqnoz və ya geri dönüş təklifi deyil və buradakı heç bir şey maliyyə məsləhətidir.',
    disclaimerText: 'DeHub ayələr hər hansı bir in-oyun və ya in-app digital ayələr və ya valyuta və ciddi investisiya deyil ki, eyni şəkildə kommunal məqsədlər üçün ciddi var. Təvazökar həyatımız davam etdikcə əlavə kommunal xidmətlər, eləcə də təsdiqlənən şəffaflığın görünməmiş səviyyələrini təklif edə bilərik. Yuxarıdakı məlumatlar yalnız şəffaflıq, təhsil və informativ məqsədlər üçün tərtib edilib. DeHub və bütün filiallar buraxdığımız hər hansı bir token və ya NFT alınması nəticəsində yaranan maliyyə itkilərinə görə heç bir məsuliyyət daşımır. Bazarlar çox dəyişkəndir. Səlahiyyət xətaları, texniki səhv, çeklər və sair kimi gözlənilməz xətalara görə bütün pulunuzu da itirə bilərsiniz. Buna görə də, yalnız itirmək üçün ödəyə biləcəyiniz məbləği daim xərcləməlisiniz.',
    useAiTitle: 'AI nəsli',
    useAiDesc: 'Hər alət üçün ayrıca abunəlik saxlamaq əvəzinə, hər bir iş işə başlamazdan əvvəl verilən qiymətlə, DeHub işarələrində, Creator Studio — şəkil, video, səs və 3D vasitəsilə AI nəsli üçün ödəniş edin.',
  },
